/// <summary>
/// 3.6.11 Sales finalisation workspace
/// <c>METSalesOrderFinalisationWorkspaceFilterStrategy</c> is used to implement the filter strategy for the sales order finalisation workspace queries
/// </summary>
[
    SysFilterExtension(SysQueryableTypeEnum::Query, SysFilterValueTypeEnum::String, queryStr(METSalesNotPickedOrders)),
    SysFilterExtension(SysQueryableTypeEnum::Query, SysFilterValueTypeEnum::Date, queryStr(METSalesNotPickedOrders)),
    SysFilterExtension(SysQueryableTypeEnum::Query, SysFilterValueTypeEnum::String, queryStr(METSalesNotDeliveredOrders)),
    SysFilterExtension(SysQueryableTypeEnum::Query, SysFilterValueTypeEnum::Date, queryStr(METSalesNotDeliveredOrders)),
    SysFilterExtension(SysQueryableTypeEnum::Query, SysFilterValueTypeEnum::String, queryStr(METSalesNotInvoicedOrders)),
    SysFilterExtension(SysQueryableTypeEnum::Query, SysFilterValueTypeEnum::Date, queryStr(METSalesNotInvoicedOrders))
]
internal final class METSalesOrderFinalisationWorkspaceFilterStrategy extends SysFilterStructureStrategyQuery implements SysIFilterStructureStrategy
{
}

Method.Source:
    /// <summary>
    /// Resolves the <c>SysIFilterValueType</c> class and adds ranges to a <c>Query</c> class.
    /// </summary>
    /// <param name="_valueType">
    /// The <c>SysIFilterValueType</c> class to be resolved.
    /// </param>
    /// <returns>
    /// true if ranges have been added; otherwise false.
    /// </returns>
    protected boolean resolve(SysIFilterValueType _valueType)
    {
        boolean isResolved = false;
        
        switch (_valueType.parmTypeIdentifier())
        {
            case extendedTypeNum(InventLocationId):               
                this.addLinkFromTableToWarehouseFilter(query.dataSourceTable(tableNum(SalesTable)),
                                                       query.dataSourceTable(tableNum(METSalesTable)),
                                                       fieldNum(SalesTable, InventLocationId),
                                                       fieldNum(METSalesTable, SecondaryInventLocationId),
                                                       filterStructureItem.parmOperator());

                isResolved = true;
                break;
            
            case extendedTypeNum(SalesShippingDate):
                this.addLinkFromTableToShipDateFilter(query.dataSourceTable(tableNum(SalesTable)),
                                                       fieldNum(SalesTable, ShippingDateConfirmed),
                                                       fieldNum(SalesTable, ShippingDateRequested),
                                                       filterStructureItem.parmOperator());

                isResolved = true;
                break;
        }

        return isResolved;
    }

/// <summary>
/// Adds a link to the <c>SysFilterTable</c> table for warehouse filter.
/// </summary>
/// <param name="_primaryRelatedTableDataSource">
/// The primary <c>QueryBuildDataSource</c> class to which the link should be added.
/// </param>
/// /// <param name="_secondaryRelatedTableDataSource">
/// The secondary <c>QueryBuildDataSource</c> class to which the link should be added.
/// </param>
/// <param name="_primaryFieldId">
/// The primary <c>FieldId</c> class for which the link should be added.
/// </param>
/// /// <param name="_secondaryFieldId">
/// The secondary <c>FieldId</c> class for which the link should be added.
/// </param>
/// <param name="_filterOperator">
/// The <c>SysFilterOperator</c> used in the range.
/// </param>
public void addLinkFromTableToWarehouseFilter(
    QueryBuildDataSource _primaryRelatedTableDataSource,
    QueryBuildDataSource _secondaryRelatedTableDataSource,
    FieldId _primaryFieldId,
    FieldId _secondaryFieldId,
    SysFilterOperator _filterOperator = SysFilterOperator::Equal)
{
    QueryBuildRange qbr = SysQueryBase::findOrCreateRange(_primaryRelatedTableDataSource, _primaryFieldId);
    qbr.status(RangeStatus::Hidden);
    // ((targetTable.TargetField <operator> sysFilterTable.ValueField) OR (sysFilterTable.ValueResolutionMethod != SysFilterValueResolutionMethod::None))
    qbr.value(strfmt('(((%1.%2 %3 %4.%5) && (%8.%9 %3 %10)) || (%8.%9 %3 %4.%5) || (%4.%6 != %7))',
        _primaryRelatedTableDataSource.name(),
        fieldId2Name(_primaryRelatedTableDataSource.table(), _primaryFieldId),
        SysFilterOperatorHelper::operator2SqlStr(_filterOperator),
        filterDatasource.name(),
        fieldId2Name(filterMetadata.parmTypeId(), filterMetadata.parmValue(filterStructureItem.parmValueType().parmType()), filterStructureItem.parmId()),
        fieldId2Name(filterMetadata.parmTypeId(), filterMetadata.parmValueResolutionMethod(), filterStructureItem.parmId()),
        int2Str(SysFilterValueResolutionMethod::None),
        _secondaryRelatedTableDataSource.name(),
        fieldId2Name(_secondaryRelatedTableDataSource.table(), _secondaryFieldId),
        SysQuery::valueEmptyString()));
}

/// <summary>
/// Adds a link to the <c>SysFilterTable</c> table for ship date filter.
/// </summary>
/// <param name="_primaryRelatedTableDataSource">
/// The primary <c>QueryBuildDataSource</c> class to which the link should be added.
/// </param>
/// <param name="_primaryFieldId">
/// The primary <c>FieldId</c> class for which the link should be added.
/// </param>
/// /// <param name="_secondaryFieldId">
/// The secondary <c>FieldId</c> class for which the link should be added.
/// </param>
/// <param name="_filterOperator">
/// The <c>SysFilterOperator</c> used in the range.
/// </param>
public void addLinkFromTableToShipDateFilter(
    QueryBuildDataSource _primaryRelatedTableDataSource,
    FieldId _primaryFieldId,
    FieldId _secondaryFieldId,
    SysFilterOperator _filterOperator = SysFilterOperator::Equal)
{
    QueryBuildRange qbr = SysQueryBase::findOrCreateRange(_primaryRelatedTableDataSource, _primaryFieldId);
    qbr.status(RangeStatus::Hidden);
    // ((targetTable.TargetField <operator> sysFilterTable.ValueField) OR (sysFilterTable.ValueResolutionMethod != SysFilterValueResolutionMethod::None))
    qbr.value(strfmt('((%1.%2 %3 %4.%5) || ((%1.%2 %3 %9) && (%1.%8 %3 %4.%5)) || (%4.%6 != %7))',
        _primaryRelatedTableDataSource.name(),
        fieldId2Name(_primaryRelatedTableDataSource.table(), _primaryFieldId),
        SysFilterOperatorHelper::operator2SqlStr(_filterOperator),
        filterDatasource.name(),
        fieldId2Name(filterMetadata.parmTypeId(), filterMetadata.parmValue(filterStructureItem.parmValueType().parmType()), filterStructureItem.parmId()),
        fieldId2Name(filterMetadata.parmTypeId(), filterMetadata.parmValueResolutionMethod(), filterStructureItem.parmId()),
        int2Str(SysFilterValueResolutionMethod::None),
        fieldId2Name(_primaryRelatedTableDataSource.table(), _secondaryFieldId),
        Date2StrXpp(dateNull())));
}
